code='''def transform(grid):
    from collections import deque
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    counts={v:sum(row.count(v) for row in g) for v in {x for row in g for x in row}}
    bg=min(counts,key=counts.get)
    seen=set()
    for r in range(h):
        for c in range(w):
            if g[r][c] != bg or (r,c) in seen: continue
            q=deque([(r,c)]); seen.add((r,c)); comp=[]; touches_edge=False
            while q:
                y,x=q.popleft(); comp.append((y,x))
                if y in (0,h-1) or x in (0,w-1): touches_edge=True
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and g[yy][xx]==bg and (yy,xx) not in seen:
                        seen.add((yy,xx)); q.append((yy,xx))
            if not touches_edge:
                for y,x in comp: g[y][x]=4
    return g
